import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Payroll — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payroll — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/payroll"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payroll — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/payroll"}]]},"headers":[],"relativePath":"user-guide/payroll.md","filePath":"user-guide/payroll.md","lastUpdated":1790937114000}'),r={name:"user-guide/payroll.md"};function s(l,e,i,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="payroll-—-user-guide" tabindex="-1">Payroll — User Guide <a class="header-anchor" href="#payroll-—-user-guide" aria-label="Permalink to &quot;Payroll — User Guide&quot;">​</a></h1><p>Enable <strong>Employees</strong> first, then install <strong>Payroll</strong> from Marketplace (free). For journal posting and bank deduction on Mark paid, also install <strong>Accounting</strong>. Nav appears under <strong>HR</strong>.</p><h2 id="payroll-profiles" tabindex="-1">Payroll profiles <a class="header-anchor" href="#payroll-profiles" aria-label="Permalink to &quot;Payroll profiles&quot;">​</a></h2><ol><li>Open <strong>Payroll profiles</strong> (or Payroll → Profiles).</li><li>Create one profile per employee: base salary, currency (defaults to workspace currency from Settings → General; editable), pay frequency (monthly / biweekly / weekly), optional effective-from date and notes.</li><li>Only <strong>active</strong> employees with a profile are included when you create a pay run.</li></ol><h2 id="working-day-basis-settings-→-attendance" tabindex="-1">Working-day basis (Settings → Attendance) <a class="header-anchor" href="#working-day-basis-settings-→-attendance" aria-label="Permalink to &quot;Working-day basis (Settings → Attendance)&quot;">​</a></h2><p>Choose how pay runs divide salary into a daily rate:</p><table tabindex="0"><thead><tr><th>Basis</th><th>Working days</th><th>Gross</th></tr></thead><tbody><tr><td><strong>Work week in period</strong> (default)</td><td>Count of work-week days in the period (Settings → work week, default Mon–Fri)</td><td>Full base salary; leave/absent/late become adjustments</td></tr><tr><td><strong>Calendar month days</strong></td><td>Days in the month when the period is the <strong>full calendar month</strong> (e.g. 1 Oct–31 Oct → 31).</td><td>Pro-rata: <code>daily × (working days − unpaid leave − absent)</code>; late ladder remains an adjustment</td></tr></tbody></table><p>Paid leave (Leave Management paid types / <code>deduct_salary = false</code>) never reduces days counted or creates unpaid-leave deductions.</p><p>When <strong>Calendar month days</strong> is selected, pay runs must start on the 1st and end on the last day of the same month (API returns 422 otherwise). Changing the basis does <strong>not</strong> recalculate existing draft pay runs — recreate drafts after switching.</p><h2 id="pay-runs" tabindex="-1">Pay runs <a class="header-anchor" href="#pay-runs" aria-label="Permalink to &quot;Pay runs&quot;">​</a></h2><ol><li>Create a pay run with period start and end dates (full month required for calendar-month basis).</li><li>The system generates a line per active employee profile using the working-day basis above: <ul><li><strong>Daily rate</strong> = base salary ÷ working days</li><li>Unpaid leave / unexcused absences / late ladder each gated by Settings → Attendance toggles</li><li>Unpaid leave comes from approved Leave Management requests whose leave type is unpaid (when that module is installed and the unpaid-leave deduction toggle is on)</li><li>Unexcused absences come from Attendance <code>absent</code> / uncovered <code>half_day</code> records that do not overlap approved leave (when Attendance is installed and the absent deduction toggle is on)</li><li>Late check-ins stay present for attendance; when the late-deduction toggle is on, a ladder (e.g. 3 lates → 1 day, 6 → 2 days) adds day-salary penalties. One late day never deducts.</li><li>Net is never negative; draft lines stay editable</li></ul></li><li>While <strong>draft</strong>, edit period notes and line gross/adjustments (net recalculates). Breakdown columns (work days, days counted, daily rate, unpaid leave, absent, lates, late days) are shown for audit.</li><li><strong>Export CSV</strong> from the pay run page downloads a register matching Person Name, Salary, Working Days, Per Day, Days Count, Salary for Days, Lates, Deduction Days, Leave Days, Deduction Amount, Payable (+ TOTALS).</li><li><strong>Approve</strong> from the pay runs list row menu, the quick peek, or the full record page (requires at least one line).</li><li><strong>Mark paid</strong> the same way. When <strong>Accounting</strong> is installed, choose <strong>Paid from</strong> (cash/bank). EloSync posts (or creates and posts) the salary accrual journal, then posts a <strong>payment</strong> journal that credits the paid-from account so that bank’s balance decreases. Without Accounting, Mark paid is status-only.</li><li>Optionally <strong>Post to journal</strong> from the full record page (approved, before payment) to create a <strong>draft</strong> accrual early (<code>Dr</code> Salary Expense <code>6400</code> / <code>Cr</code> Salaries Payable <code>2200</code>). Mark paid posts that draft if it still exists, then posts the payment.</li></ol><h2 id="my-salary-slips-employees" tabindex="-1">My salary slips (employees) <a class="header-anchor" href="#my-salary-slips-employees" aria-label="Permalink to &quot;My salary slips (employees)&quot;">​</a></h2><p>Linked employees with <code>payroll.view_own</code> (staff by default) can open <strong>My salary slips</strong> and download PDF copies of their <strong>paid</strong> pay-run lines for personal records. Managers with <code>payroll.view</code> can also download line PDFs from a paid pay run’s lines table (<strong>Download</strong>).</p><p>Pay slip PDFs use the same company branding as invoices and quotations: logo and button color (when <strong>Branded</strong> is entitled), company name/tagline/address/phone/website from <strong>Settings → Branding</strong>, and tax registration ID from <strong>Settings → General</strong> when set. Each slip shows employee details, period attendance breakdown (including daily rate and days counted), salary for days, deduction amount, and payable salary.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft → approved → paid</span></span></code></pre></div><p>Only drafts are editable or soft-deletable. Accounting integration requires active cash/bank (for Mark paid) and Salary Expense / Salaries Payable accounts (starter codes <code>6400</code> / <code>2200</code>, or overrides on Post).</p>',17)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
